<?php
declare(strict_types=1);require_once __DIR__.'/config/erp.php';$pdo=srnu_db();$id=(int)($_GET['id']??$_POST['id']??0);$c=srnu_obtener_cotizacion($id);if(!$c){http_response_code(404);exit('No encontrada');}
if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['generar'])){$inicio=epost('fecha_inicio',date('Y-m-d'));foreach($c['items'] as $it){$m=(int)($it['garantia_meses']??0);if($m<=0)continue;$chk=$pdo->prepare('SELECT id,fecha_fin FROM garantias WHERE cotizacion_id=? AND item_id=?');$chk->execute([$id,$it['id']]);$g=$chk->fetch();if(!$g){$fin=date('Y-m-d',strtotime('+'.$m.' months',strtotime($inicio)));$pdo->prepare('INSERT INTO garantias(cotizacion_id,item_id,concepto,fecha_inicio,fecha_fin,estado) VALUES(?,?,?,?,?,?)')->execute([$id,$it['id'],$it['concepto'],$inicio,$fin,'Vigente']);$gid=(int)$pdo->lastInsertId();}else{$gid=(int)$g['id'];$fin=$g['fecha_fin'];}$ch=$pdo->prepare("SELECT id FROM postventa_recordatorios WHERE garantia_id=? AND tipo='Garantía'");$ch->execute([$gid]);if(!$ch->fetch())$pdo->prepare("INSERT INTO postventa_recordatorios(cotizacion_id,garantia_id,tipo,fecha_recordatorio,descripcion,estado) VALUES(?,?,'Garantía',?,?,'Pendiente')")->execute([$id,$gid,date('Y-m-d',max(time(),strtotime($fin.' -30 days'))),'Revisar garantía próxima a vencer: '.$it['concepto']]);}ego('garantias.php?id='.$id);}
$pdo->prepare("UPDATE garantias SET estado=IF(fecha_fin<CURDATE(),'Vencida','Vigente') WHERE cotizacion_id=? AND estado<>'Cancelada'")->execute([$id]);$st=$pdo->prepare('SELECT * FROM garantias WHERE cotizacion_id=? ORDER BY fecha_fin');$st->execute([$id]);$gs=$st->fetchAll();?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Garantías · <?=eh($c['folio'])?></title><?=srnu_ui_head()?></head><body><?php srnu_appbar('cotizaciones');?><main class="w"><div class="srnu-page-heading"><div><h1>Garantías</h1><p><?=eh($c['folio'])?> · <?=eh($c['cliente'])?> · <?=eh($c['vehiculo'])?></p></div><div class="toolbar"><a class="btn light" href="cotizaciones.php">← Cotizaciones</a><a class="btn light" href="postventa.php">Postventa</a></div></div><section class="panel" style="padding:18px"><form method="post" class="toolbar"><input type="hidden" name="id" value="<?=$id?>"><label>Inicio <input type="date" name="fecha_inicio" value="<?=date('Y-m-d')?>"></label><button class="btn blue" name="generar" value="1">Generar garantías configuradas</button></form></section><section class="tablebox" style="margin-top:16px"><table><thead><tr><th>Concepto</th><th>Inicio</th><th>Vence</th><th>Estado</th></tr></thead><tbody><?php foreach($gs as $g):?><tr><td><?=eh($g['concepto'])?></td><td><?=edate($g['fecha_inicio'])?></td><td><?=edate($g['fecha_fin'])?></td><td><span class="badge <?=$g['estado']==='Vigente'?'badge-green':'badge-red'?>"><?=eh($g['estado'])?></span></td></tr><?php endforeach;?></tbody></table></section></main></body></html>
